import{_ as s,C as r,o,c as d,j as a,a as n,E as i,ak as h}from"./chunks/framework.sV-XtlWr.js";const l="/screenshots/saved-dashboard.png",c="/screenshots/dashboard-editor.png",v=JSON.parse('{"title":"Dashboards","description":"","frontmatter":{"title":"Dashboards","lang":"en-US"},"headers":[],"relativePath":"features/dashboards.md","filePath":"features/dashboards.md","lastUpdated":1790415794000}'),p={name:"features/dashboards.md"};function m(u,e,g,b,w,f){const t=r("Needs");return o(),d("div",null,[e[0]||(e[0]=a("h1",{id:"dashboards",tabindex:"-1"},[n("Dashboards "),a("a",{class:"header-anchor",href:"#dashboards","aria-label":'Permalink to "Dashboards"'},"​")],-1)),i(t,{reporter:""}),e[1]||(e[1]=h('<p>A <strong>dashboard</strong> is a named arrangement of <a href="./analytics.html">analytics</a> widgets in bands, with a default <a href="./analytics.html#scope">scope</a>: its projects, filters and period. The analytics page is the built-in <strong>Overview</strong> dashboard; anyone can keep their own dashboards, share them with the team, schedule them as a <a href="./quality-reports.html">quality report</a>, and put them on a wall screen.</p><p><img src="'+l+'" alt="A shared dashboard: the checkout smoke tests over the current sprint, with a list, the period&#39;s releases and a note"></p><h2 id="built-in-and-saved-dashboards" tabindex="-1">Built-in and saved dashboards <a class="header-anchor" href="#built-in-and-saved-dashboards" aria-label="Permalink to &quot;Built-in and saved dashboards&quot;">​</a></h2><p>The header&#39;s switcher lists every dashboard you can open, with a search:</p><ul><li><strong>Built-in</strong>: Overview (the analytics page, four bands and fifteen widgets), and the report dashboards Executive, Engineering and Gaps digest (the last one only where the <a href="./scenario-gaps.html">Test Map</a> is not declined). A built-in dashboard cannot be changed, only duplicated.</li><li><strong>Shared</strong>: saved dashboards someone shared with every signed-in user.</li><li><strong>Personal</strong>: your private dashboards.</li><li><strong>Unused</strong>: shared dashboards nobody opened for 90 days, where their owner or an administrator can delete them.</li></ul><p><code>/analytics/d/&lt;id&gt;</code> opens one dashboard; <em>Manage dashboards</em> (<code>/analytics/dashboards</code>) lists them all, with <em>New dashboard</em> (empty, or a copy of any dashboard you can open), <em>Duplicate</em> and <em>Delete</em>.</p><h2 id="your-default-dashboard" tabindex="-1">Your default dashboard <a class="header-anchor" href="#your-default-dashboard" aria-label="Permalink to &quot;Your default dashboard&quot;">​</a></h2><p><code>/analytics</code> opens, in this order: the dashboard you picked with <em>Make it my default</em> (kept in this browser), the dashboard an administrator set for everyone under <em>Manage dashboards</em> (a built-in or a shared one), else Overview. Overview keeps the scope you used last in this browser; another dashboard opens on its own saved scope. Either way the address carries the scope, so a copied link shows what you saw.</p><h2 id="editing-a-dashboard" tabindex="-1">Editing a dashboard <a class="header-anchor" href="#editing-a-dashboard" aria-label="Permalink to &quot;Editing a dashboard&quot;">​</a></h2><p><em>Edit</em> (or <em>Duplicate</em>, on a dashboard you cannot change) turns the page into the editor:</p><ul><li>Each band gets a title, a description, <em>Add widget</em> and a menu to move or remove it; <em>Add band</em> is at the bottom.</li><li>Each widget gets a menu: <em>Configure</em>, <em>Half width</em> or <em>Full width</em>, <em>Move up</em>, <em>Move down</em>, <em>Move to band</em>, <em>Duplicate</em>, <em>Remove</em>. Moves are buttons, so the editor works on a phone and from a keyboard. Below the <code>xl</code> breakpoint every widget is full width.</li><li>The <strong>Filters</strong> block, titled <em>Default filters</em>, sets the scope the dashboard opens with.</li><li>Widgets preview from your unsaved changes. <em>Save</em> writes them; <em>Save as…</em> writes a new dashboard.</li></ul><p><img src="'+c+'" alt="The dashboard editor: band title and description, Add widget, and a widget&#39;s menu"></p><p>If someone saved the dashboard while you were editing it, <em>Save</em> says so and offers to reload their version or save yours as a copy; nothing is overwritten.</p><h3 id="widgets" tabindex="-1">Widgets <a class="header-anchor" href="#widgets" aria-label="Permalink to &quot;Widgets&quot;">​</a></h3><p><em>Add widget</em> lists every widget, grouped by the band it usually belongs to, with a search: the fifteen of Overview, the report widgets (verdict, what is being done, risks, scenario gaps), the engineering widgets (ownership, environment comparison, movers; see <a href="./analytics-widgets.html">Analytics widgets</a>), and:</p><ul><li><strong>Metric</strong>: one number of the metric catalog, drawn as a number, a line, bars, a table or a heatmap (below).</li><li><strong>List</strong>: the latest runs of the period, the open failure causes with the most occurrences, the flakiest tests, or the highest-scored open scenario gaps, top 5 to 25, each linking to its page.</li><li><strong>Timeline markers</strong>: the <a href="./timeline-markers.html">timeline markers</a> of the period, optionally of some categories.</li><li><strong>Note</strong>: text in Markdown. Raw HTML is shown as text, so a shared dashboard cannot carry a script.</li><li><strong>One project</strong>: spec health, slowest tests, performance trend, timeout opportunities and selection health, the analyses of the project page. They need a scope with exactly one project and say so otherwise.</li></ul><p>A widget a later release removed shows &quot;This widget is no longer available&quot; instead of breaking the dashboard.</p><h3 id="the-metric-widget" tabindex="-1">The metric widget <a class="header-anchor" href="#the-metric-widget" aria-label="Permalink to &quot;The metric widget&quot;">​</a></h3><p>Pick a metric, a display and, optionally, a <strong>breakdown</strong>: &quot;wasted CI minutes by browser&quot;, &quot;pass rate by project tag&quot;, &quot;open failure causes by assignee&quot;. The breakdowns a metric offers depend on what it counts:</p><table tabindex="0"><thead><tr><th>Metric counts</th><th>Breakdowns</th></tr></thead><tbody><tr><td>Runs and tests (pass rates, durations, wasted and CI minutes, regressions)</td><td>project, project tag, environment, branch, run kind; browser, test tag, owner, priority, feature, spec directory</td></tr><tr><td>Failure causes</td><td>project, project tag, error type, status, assignee</td></tr><tr><td>Quarantined tests</td><td>project, project tag, owner, test tag</td></tr></tbody></table><p>With a breakdown, <em>Bars</em> and <em>Table</em> show one row per group for the period, <em>Line</em> one line per group (the first eight), <em>Heatmap</em> one row of buckets per group. Groups are sorted worst first; the top 5 to 25 are shown, the rest grouped as <em>Other</em>. Breakdowns by project, environment, branch or run kind read the daily rollups, so they reach as far back as the rollups do; breakdowns by test or browser read the stored executions, as far back as retention keeps them.</p><h3 id="periods-and-filters-per-widget" tabindex="-1">Periods and filters per widget <a class="header-anchor" href="#periods-and-filters-per-widget" aria-label="Permalink to &quot;Periods and filters per widget&quot;">​</a></h3><p><em>Configure</em> also sets a widget&#39;s own scope: a period that replaces the dashboard&#39;s (a <em>Last 7 days</em> number on a quarterly dashboard), and filters that <strong>narrow</strong> the dashboard&#39;s (only some projects, a selection, test tags, browsers). A widget never widens the dashboard&#39;s filters, so what a dashboard covers can be read off its <strong>Filters</strong> block.</p><h2 id="sharing-and-access" tabindex="-1">Sharing and access <a class="header-anchor" href="#sharing-and-access" aria-label="Permalink to &quot;Sharing and access&quot;">​</a></h2><ul><li>A dashboard is <strong>private</strong> (its owner) or <strong>shared</strong> (listed for every signed-in user). Anyone signed in keeps private dashboards; sharing needs the reporter or administrator role.</li><li>A shared dashboard is changed by its owner or an administrator; everyone else duplicates it.</li><li>With authentication off, every dashboard is shared.</li><li><strong>A dashboard grants no access.</strong> Every widget is computed for the projects you can open, and the line under the dashboard&#39;s name says how many projects of the dashboard&#39;s scope are hidden from you (&quot;1 project hidden (no access)&quot;).</li><li>A private dashboard whose owner is deleted goes with the nightly orphan sweep; a shared one stays, editable by administrators.</li></ul><h2 id="live-refresh-and-tv-mode" tabindex="-1">Live refresh and TV mode <a class="header-anchor" href="#live-refresh-and-tv-mode" aria-label="Permalink to &quot;Live refresh and TV mode&quot;">​</a></h2><p>An open dashboard refreshes a widget when a run of one of its projects finishes, at most once every 30 seconds per widget. Widget answers are cached on the server for 60 seconds.</p><p><strong>TV mode</strong> (<em>TV mode</em> in the menu, or <code>?tv=1</code>) is for a wall screen: no navigation, larger type, and a full refresh every five minutes on top of the live one. Add <code>?cycle=12,15&amp;every=60</code> to rotate through several dashboards, one every 60 seconds (15 at least). TV mode needs a signed-in session; a wall screen with nobody signed in opens a <a href="./share-links.html#live-dashboard-links">live dashboard link</a> instead.</p><h2 id="scheduling-and-exporting-a-dashboard" tabindex="-1">Scheduling and exporting a dashboard <a class="header-anchor" href="#scheduling-and-exporting-a-dashboard" aria-label="Permalink to &quot;Scheduling and exporting a dashboard&quot;">​</a></h2><p><em>Export</em> renders the dashboard on screen as a <a href="./quality-reports.html">quality report</a> (the saved dashboard is offered first), and <em>Schedule…</em> creates a <a href="./quality-reports.html#report-schedules">report schedule</a> on it. Deleting a dashboard that schedules render names them first; they stop, shown as inactive with the reason on the Reports page, until their owner picks another dashboard.</p><h2 id="from-an-agent" tabindex="-1">From an agent <a class="header-anchor" href="#from-an-agent" aria-label="Permalink to &quot;From an agent&quot;">​</a></h2><p>The <a href="./mcp.html">MCP server</a> has <code>list_dashboards</code> and <code>get_dashboard</code>, which returns every widget&#39;s data, the JSON the page renders, over the dashboard&#39;s scope; each key you pass replaces the dashboard&#39;s.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./analytics.html">Analytics</a>: the scope, the periods and the widgets of Overview</li><li><a href="./quality-reports.html">Quality reports</a>: a dashboard as a document, on a schedule</li></ul>',34))])}const k=s(p,[["render",m]]);export{v as __pageData,k as default};
